package app.tauri.tao_mobile;

import android.content.Intent;

// Native functions implemented in `src/lib.rs`.
public final class Rust {
    static {
        System.loadLibrary("tao_mobile");
    }

    private Rust() {}

    // bindings generated by `tao::android_binding!`
    public static native void onFirstActivityCreate();
    public static native void onCreate(MainActivity activity);
    public static native void onStart(MainActivity activity);
    public static native void onResume(MainActivity activity);
    public static native void onPause(MainActivity activity);
    public static native void onStop(MainActivity activity);
    public static native void onDestroy(MainActivity activity);
    public static native void onWindowFocusChanged(MainActivity activity, boolean focus);
    public static native void onLowMemory();
    public static native void onNewIntent(Intent intent);

    // example specific
    public static native void requestWindow();
}
